94. {
95.     [Description("Search the web for information on a query. Returns a list of search result snippets.")]
96.     public async Task<string> SearchWeb(
97.         [Description("The search query string")] string query)
98.     {
99.         // Uses DuckDuckGo HTML endpoint for demo purposes.
100.         // In production, replace with a proper search API (Bing Search API, Google Custom Search, etc.).
101.         using var http = new HttpClient();
102.         http.DefaultRequestHeaders.UserAgent.ParseAdd(
103.             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
104. 
105.         try
106.         {
107.             var encoded = Uri.EscapeDataString(query);
108.             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
109.             var html = await http.GetStringAsync(url);
110. 
111.             var snippets = ExtractSnippets(html, maxResults: 5);
112.             if (snippets.Count == 0)
113.                 return $"No results found for '{query}'.";
114. 
115.             var sb = new System.Text.StringBuilder();
116.             sb.AppendLine($"Search results for '{query}':");
117.             for (int i = 0; i < snippets.Count; i++)
118.             {
119.                 sb.AppendLine($"{i + 1}. {snippets[i]}");
120.             }
121.             return sb.ToString();
122.         }
123.         catch (Exception ex)
124.         {
125.             return $"Search failed for '{query}': {ex.Message}";
126.         }
127.     }
128. 
129.     [Description("Save a research note with a title and content for later reference.")]
130.     public string SaveNote(
131.         [Description("A short descriptive title for the note")] string title,
132.         [Description("The content/findings to save")] string content)
133.     {
134.         notebook.Add(title, content);
135.         return $"Note saved: '{title}' ({content.Length} chars)";
136.     }
137. 
138.     [Description("Retrieve all saved research notes.")]
139.     public string GetNotes()
140.     {
141.         var notes = notebook.All;
142.         if (notes.Count == 0)
143.             return "No notes saved yet.";
144. 
145.         var sb = new System.Text.StringBuilder();
146.         sb.AppendLine($"=== {notes.Count} saved note(s) ===");
147.         foreach (var (title, content) in notes)
148.         {
149.             sb.AppendLine($"\n## {title}\n{content}");
150.         }
151.         return sb.ToString();
152.     }
