154.     private static List<string> ExtractSnippets(string html, int maxResults)
155.     {
156.         var results = new List<string>();
157.         var snippetMarker = "result__snippet";
158.         var pos = 0;
159.         while (results.Count < maxResults)
160.         {
161.             pos = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
162.             if (pos < 0) break;
163. 
164.             var start = html.IndexOf('>', pos);
165.             if (start < 0) break;
166.             start++;
167. 
168.             var end = html.IndexOf("</", start, StringComparison.Ordinal);
169.             if (end < 0) break;
170. 
171.             var snippet = html[start..end]
172.                 .Replace("<b>", "").Replace("</b>", "")
173.                 .Replace("&amp;", "&").Replace("&quot;", "\"")
174.                 .Replace("&#x27;", "'").Replace("&lt;", "<").Replace("&gt;", ">")
175.                 .Trim();
176. 
177.             if (snippet.Length > 10)
178.                 results.Add(snippet);
179. 
180.             pos = end;
181.         }
182.         return results;
183.     }
