 using System.ComponentModel;
 using Microsoft.Extensions.AI;
 using Microsoft.Agents.AI;
 using OpenAI;

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 IChatClient chatClient = new ChatClientBuilder(
         new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
     .UseFunctionInvocation()
     .Build();

 var notebook = new Notebook();
 var researchTools = new ResearchTools(notebook);

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(researchTools.SearchWeb),
     AIFunctionFactory.Create(researchTools.SaveNote),
     AIFunctionFactory.Create(researchTools.GetNotes),
 };

 const string instructions = """
     You are a research assistant. When given a topic:
     1. Search the web for relevant information using multiple queries.
     2. Save important findings as notes with clear titles.
     3. After gathering enough information, retrieve all notes and provide
        a well-structured summary with key findings and sources.
     Be thorough — perform at least 2-3 searches from different angles.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 Console.WriteLine("🔬 Research Agent");
 Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("> ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notebook.Clear();

     Console.WriteLine();
     await foreach (var update in agent.RunStreamingAsync(
         $"Research the following topic and provide a summary: {topic}"))
     {
         if (!string.IsNullOrEmpty(update.Text))
         {
             Console.Write(update.Text);
         }
     }
     Console.WriteLine("\n");
 }

 // --- Tool definitions ---

 public sealed class Notebook
 {
     private readonly List<(string Title, string Content)> _notes = [];
     private readonly Lock _lock = new();

     public void Add(string title, string content)
     {
         lock (_lock) _notes.Add((title, content));
     }

     public IReadOnlyList<(string Title, string Content)> All
     {
         get { lock (_lock) return [.. _notes]; }
     }

     public void Clear()
     {
         lock (_lock) _notes.Clear();
     }
 }

 public sealed class ResearchTools(Notebook notebook)
 {
     [Description("Search the web for information on a query. Returns a list of search result snippets.")]
     public async Task<string> SearchWeb(
         [Description("The search query string")] string query)
     {
         // Uses DuckDuckGo HTML endpoint for demo purposes.
         // In production, replace with a proper search API (Bing Search API, Google Custom Search, etc.).
         using var http = new HttpClient();
         http.DefaultRequestHeaders.UserAgent.ParseAdd(
             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await http.GetStringAsync(url);

             var snippets = ExtractSnippets(html, maxResults: 5);
             if (snippets.Count == 0)
                 return $"No results found for '{query}'.";

             var sb = new System.Text.StringBuilder();
             sb.AppendLine($"Search results for '{query}':");
             for (int i = 0; i < snippets.Count; i++)
             {
                 sb.AppendLine($"{i + 1}. {snippets[i]}");
             }
             return sb.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}";
         }
     }

     [Description("Save a research note with a title and content for later reference.")]
     public string SaveNote(
         [Description("A short descriptive title for the note")] string title,
         [Description("The content/findings to save")] string content)
     {
         notebook.Add(title, content);
         return $"Note saved: '{title}' ({content.Length} chars)";
     }

     [Description("Retrieve all saved research notes.")]
     public string GetNotes()
     {
         var notes = notebook.All;
         if (notes.Count == 0)
             return "No notes saved yet.";

         var sb = new System.Text.StringBuilder();
         sb.AppendLine($"=== {notes.Count} saved note(s) ===");
         foreach (var (title, content) in notes)
         {
             sb.AppendLine($"\n## {title}\n{content}");
         }
         return sb.ToString();
     }

     private static List<string> ExtractSnippets(string html, int maxResults)
     {
         var results = new List<string>();
         var snippetMarker = "result__snippet";
         var pos = 0;
         while (results.Count < maxResults)
         {
             pos = html.IndexOf(snippetMarker, pos, StringComparison.Ordinal);
             if (pos < 0) break;

             var start = html.IndexOf('>', pos);
             if (start < 0) break;
             start++;

             var end = html.IndexOf("</", start, StringComparison.Ordinal);
             if (end < 0) break;

             var snippet = html[start..end]
                 .Replace("<b>", "").Replace("</b>", "")
                 .Replace("&amp;", "&").Replace("&quot;", "\"")
                 .Replace("&#x27;", "'").Replace("&lt;", "<").Replace("&gt;", ">")
                 .Trim();

             if (snippet.Length > 10)
                 results.Add(snippet);

             pos = end;
         }
         return results;
     }
 }
